previewCss:
.darma-loader-darma-b12-elevator-shaft { --accent: var(--loader-color, #6366f1); --accent-2: var(--loader-secondary-color, #22d3ee); width: calc(var(--loader-size, 108px) * .52); height: var(--loader-size, 108px); position: relative; overflow: hidden; border-radius: 8%; background: repeating-linear-gradient(to bottom, #e2e8f0 0 2px, #f1f5f9 2px 32%); box-shadow: inset 0 0 0 2px #cbd5e1; }
.darma-loader-darma-b12-elevator-shaft .darma-loader-darma-b12-elevator-shaft__car { position: absolute; left: 12%; width: 76%; height: 26%; border-radius: 4px; background: linear-gradient(var(--accent), var(--accent-2)); box-shadow: 0 3px 8px rgba(15, 23, 42, .28); animation: darma-loader-darma-b12-elevator-shaft-ride calc(var(--loader-speed, 1s) * 3.2) cubic-bezier(.45, 0, .35, 1) infinite; }
.darma-loader-darma-b12-elevator-shaft .darma-loader-darma-b12-elevator-shaft__car::after { content: ''; position: absolute; top: 8%; left: calc(50% - 1px); width: 2px; height: 84%; background: rgba(255, 255, 255, .6); }
@keyframes darma-loader-darma-b12-elevator-shaft-ride { 0%, 10% { top: 68%; } 35%, 45% { top: 36%; } 70%, 82% { top: 4%; } 100% { top: 68%; } }

